import {StudioCamera} from './studio-camera.js';
const J=globalThis.window?.jarvis;
if(J&&(new URLSearchParams(location.search).get('view')||'main')==='main'){
 const api=(method,data={})=>J.call('core',{method,data}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const camera=new StudioCamera(navigator.mediaDevices);let panel,project,state,previous,masked=false,opening=false,busy=false,timer,dirty=false;
 const say=t=>{if(panel)panel.querySelector('[role=status]').textContent=t;};
 async function close(){if(busy)return;camera.stop();clearInterval(timer);panel?.remove();panel=null;project=null;dirty=false;if(masked)await J.call('tabs-show',true).catch(()=>{});masked=false;window.__jarvisHolo?.pauseAll(false);previous?.focus?.();}
 async function show(){if(panel||opening)return;opening=true;try{state=await api('studio-list');previous=document.activeElement;masked=await J.call('tabs-state').catch(()=>false);if(masked)await J.call('tabs-show',false);window.__jarvisHolo?.pauseAll(true);panel=document.createElement('section');panel.className='wb-panel ps-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Product Studio');panel.innerHTML='<header><div><small>FROM PRODUCT TO PICTURE</small><h2>Product Studio</h2></div><button data-act="close">Close</button></header><div class="wb-body"><main></main></div><p class="wb-status" role="status"></p>';document.body.append(panel);panel.onclick=e=>{const b=e.target.closest('[data-act]');if(b)run(b.dataset.act,b).catch(e=>say(e.message));};panel.onsubmit=e=>{e.preventDefault();submit(e.target).catch(e=>say(e.message));};panel.oninput=e=>{if(e.target.closest('[data-brief]'))dirty=true;};home();panel.querySelector('button').focus();timer=setInterval(()=>refreshJob().catch(()=>{}),5000);}catch(e){await close();alert('Product Studio: '+e.message);}finally{opening=false;}}
 const main=()=>panel?.querySelector('main');
 function home(){camera.stop();project=null;dirty=false;main().innerHTML=`<p>Photograph your product, describe its scene, then review a generation request. Pictures and drafts stay on this PC until you approve a clip.</p><div class="wb-actions"><button class="wb-primary" data-act="import">Choose product photo</button><button data-act="camera">Use camera</button></div><p>JPEG or PNG up to 6 MB. Camera capture uses video only. Your picture’s shape determines the clip’s orientation.</p>${state.error?`<p>${esc(state.error)}</p>`:''}<details><summary>Higgsfield connection · ${state.ready?'credentials saved':'not connected'}</summary><p>Use API credentials from your Higgsfield developer account. A website subscription or Codex plugin connection does not supply this key. Clips use paid API credits.</p><form data-key><label>API key ID:secret<input type="password" name="key" autocomplete="new-password" placeholder="key_id:key_secret"></label><button>Save connection</button><button type="button" data-act="disconnect">Remove connection</button></form></details><h3>Your projects</h3><div class="ps-library">${state.projects.map(p=>`<button class="ps-project" data-act="project" data-id="${p.id}"><img src="${esc(p.photoUrl)}" alt=""><strong>${esc(p.product||'Untitled product')}</strong><span>${esc(p.job?.state||'Draft')}</span></button>`).join('')||'<p>Start with a clear photo showing the whole product and its label.</p>'}</div>`;}
 function drawProject(){camera.stop();dirty=false;main().innerHTML=`<button data-act="home">All projects</button><div class="ps-editor"><div><img class="ps-photo" src="${esc(project.photoUrl)}" alt="Saved reference product"><p>This is the exact picture sent after approval. Generated labels and product details still need your review.</p></div><form data-brief><label>Product name<input name="product" maxlength="160" required value="${esc(project.product)}"></label><label>Describe the scene<textarea name="scene" rows="5" minlength="12" maxlength="1600" required placeholder="A perfume bottle on ice, cold mist clearing, slow close-up, soft blue light…">${esc(project.scene)}</textarea></label><div class="wb-grid"><label>Silent clip length<select name="duration"><option value="5" ${project.duration===5?'selected':''}>5 seconds</option><option value="10" ${project.duration===10?'selected':''}>10 seconds</option></select></label><label>Maximum price estimate (US$)<input name="maxCost" type="number" min="0.01" max="20" step="0.01" value="${project.maxCost}"></label></div><p>Kling 2.5 Turbo Pro. JARVIS checks Higgsfield’s live estimate against this limit and your daily Core allowance before starting. Final billing is set by Higgsfield.</p><div class="wb-actions"><button>Save brief</button><button type="button" data-act="export">Save and export brief</button><button type="button" class="wb-primary" data-act="request">Save and request approval</button></div></form></div><div data-job></div>`;drawJob();}
 function drawJob(){const box=panel?.querySelector('[data-job]');if(!box)return;const j=project.job;if(!j){box.innerHTML='<p>Nothing has been uploaded or generated for this project.</p>';return;}const playing=box.querySelector('video');if(playing&&j.state==='ready')return;box.innerHTML=`<article class="wb-item"><h3>${esc(j.state==='ready'?'Your clip is ready':j.state==='needs check'?'Check provider history':j.state.replaceAll('_',' '))}</h3>${j.error?`<p>${esc(j.error)}</p>`:''}<p>${j.estimate!==undefined?'Reserved estimate: US$'+Number(j.estimate).toFixed(2)+'. ':''}${j.requestId?'Request: '+esc(j.requestId):''}</p>${j.state==='ready'?`<video controls playsinline preload="metadata" src="${esc(project.videoUrl)}"></video><p>Saved in Documents → JARVIS → Product Studio. Check labels and movement before sharing.</p><button data-act="open">Open saved clip</button>`:`<button data-act="refresh">Check progress</button>${j.state==='queued'?'<button data-act="cancel">Cancel queued clip</button>':''}<p>You can keep working while it generates. Closing this panel keeps the request; JARVIS checks it while the app is running. Uncertain submissions are never repeated automatically.</p>`}</article>`;}
 async function refreshJob(){if(!panel||!project||busy)return;const s=await api('studio-list');if(!panel||!project)return;state=s;const p=s.projects.find(p=>p.id===project.id);if(p){project.job=p.job;project.videoUrl=p.videoUrl;drawJob();}}
 async function guard(fn){if(busy)return;busy=true;panel?.querySelectorAll('button').forEach(b=>b.disabled=true);try{return await fn();}finally{busy=false;panel?.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 async function save(validate=false){const form=panel.querySelector('[data-brief]');if(validate&&!form.reportValidity())throw Error('Complete the product name and scene first.');project=await api('studio-edit',{...Object.fromEntries(new FormData(form)),id:project.id});dirty=false;return project;}
 async function leave(){if(dirty)await save();state=await api('studio-list');home();}
 async function submit(form){if(form.hasAttribute('data-key'))await guard(async()=>{state.ready=await J.call('studio-key',new FormData(form).get('key'));form.reset();say('Credentials saved on this PC. Request approval from a product project to start.');});else await guard(async()=>{await save();say('Scene brief saved.');});}
 async function run(act,b){if(busy)return;if(act==='close'){if(dirty)await guard(save);return close();}if(act==='home')return guard(leave);if(act==='project'){project=state.projects.find(p=>p.id===b.dataset.id);drawProject();return;}
  if(act==='camera'){main().innerHTML='<button data-act="home">Back</button><h3>Show the whole product</h3><video class="ps-camera" autoplay muted playsinline></video><p>Position the product, then capture one still. No microphone or background recording.</p><button data-act="capture" disabled>Capture product</button>';const video=main().querySelector('video');say('Waiting for camera permission…');try{if(await camera.start(video)){panel.querySelector('[data-act=capture]').disabled=false;say('Camera ready.');}}catch(e){camera.stop();say('Camera unavailable: '+e.message+'. Use Choose product photo instead.');}return;}
  if(act==='import'||act==='capture')return guard(async()=>{let p;if(act==='import')p=await J.call('studio-photo');else{const v=main().querySelector('video');if(!v.videoWidth)throw Error('Wait until the camera picture is visible.');const c=document.createElement('canvas'),scale=Math.min(1,1400/v.videoWidth);c.width=Math.round(v.videoWidth*scale);c.height=Math.round(v.videoHeight*scale);c.getContext('2d').drawImage(v,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.85));camera.stop();if(!blob)throw Error('Camera picture could not be saved.');p=await J.call('studio-capture',new Uint8Array(await blob.arrayBuffer()));}if(p){project=p;drawProject();say('Photo saved locally. Describe the scene.');}});
  if(act==='request'){const r=await guard(async()=>{await save(true);return api('studio-request',{id:project.id});});if(r){await close();window.__jarvisCore?.show('needs');}return;}
  return guard(async()=>{if(act==='export'){await save(true);await api('studio-export',{id:project.id});say('Scene brief exported.');}if(act==='disconnect'){state.ready=await J.call('studio-key','');home();say('API credentials removed.');}if(act==='refresh'||act==='cancel'){project=await api(act==='refresh'?'studio-poll':'studio-cancel',{id:project.id});drawJob();}if(act==='open')await api('studio-open',{id:project.id});});
 }
 addEventListener('keydown',e=>{if(!panel)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();run('close').catch(e=>say(e.message));}if(e.key==='Tab'){const a=[...panel.querySelectorAll('button:not(:disabled),input,textarea,select,video[controls],summary')].filter(e=>e.getClientRects().length);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus();}}},true);
 window.__jarvisProductStudio={show,close};addEventListener('pagehide',()=>{camera.stop();clearInterval(timer);});
}
